<?php
if(!isset($assignments,$db)){http_response_code(404);exit;}
$user=(int)$_SESSION['user_id'];$a=$assignments[0];$class=(int)$a['kelas_id'];$now=(string)$db->query('SELECT CURRENT_TIMESTAMP')->fetchColumn();$today=substr($now,0,10);
$plan=null;$configuration='';try{$plan=kbm_pilihan_slots($db,$a,$today);}catch(InvalidArgumentException $e){$configuration=$e->getMessage();}
$slots=[];foreach($plan['slots']??[] as $slot)if($slot['jenis']==='JP')$slots[(int)$slot['jp']]=$slot;
$rows=array_values(array_filter(kbm_day_report($db,$today),fn($r)=>(int)$r['kelas_id']===$class));$open=kbm_open_meetings($db,$class);
$jpRows=$jpCodes=$jpLocked=[];
foreach($rows as $r){$code=kbm_meeting_status($r,$now)['code'];for($n=(int)$r['jp_mulai'];$n<=(int)$r['jp_selesai'];$n++){$jpRows[$n]=$r;$jpCodes[$n]=$code;if(in_array($code,['selesai','guru_tidak_masuk','guru_hanya_tugas'],true))$jpLocked[$n]=true;}}
$jp=is_string($_GET['jp']??null)&&preg_match('/^[1-6]$/D',$_GET['jp'])?(int)$_GET['jp']:0;
if(!$jp)foreach($slots as $n=>$s)if($s['mulai']!==null&&$today.' '.$s['mulai']<=$now&&$now<$today.' '.$s['selesai']){$jp=$n;break;}
if(!$jp||isset($jpLocked[$jp])){$jp=0;for($n=1;$n<=6;$n++)if(!isset($jpLocked[$n])){$jp=$n;break;}}
$allReported=$jp===0;if(!$jp)$jp=1;$jpEnd=is_string($_GET['akhir']??null)&&preg_match('/^[1-6]$/D',$_GET['akhir'])?max($jp,(int)$_GET['akhir']):$jp;$selected=null;
foreach($rows as $r)if($jp>=$r['jp_mulai']&&$jp<=$r['jp_selesai']){$selected=$r;break;}
if($selected&&!isset($_GET['akhir'])&&($_GET['pilih_awal']??'')!=='1'){$jp=(int)$selected['jp_mulai'];$jpEnd=(int)$selected['jp_selesai'];}
if($selected&&((int)$selected['jp_mulai']!==$jp||(int)$selected['jp_selesai']!==$jpEnd))$selected=null;
$slot=null;try{if($plan)$slot=kbm_pilihan_block($plan['slots'],$jp,$jpEnd);}catch(InvalidArgumentException $e){$rangeError=$e->getMessage();}
$cleared=($_GET['reset']??'')==='1';if($cleared||$allReported){$selected=null;$slot=null;}
$rangeLabel='JP '.$jp.($jpEnd!==$jp?'–'.$jpEnd:'');
$teacherBlockedReason='';
if($cleared)$teacherBlockedReason='Pilih JP awal dan JP akhir terlebih dahulu, lalu pilih guru.';
elseif(!$slot)$teacherBlockedReason=$rangeError??($configuration?:'Pilihan JP belum tersedia.');
elseif($open)$teacherBlockedReason='Masih ada pertemuan yang belum check-out. Tekan Check-out Guru pada catatan aktif di atas sebelum memilih guru berikutnya.';
if($allReported)$teacherBlockedReason='Semua JP hari ini sudah dilaporkan. Catatan tetap dapat dilihat pada tabel.';
else for($n=$jp;$n<=$jpEnd;$n++)if(isset($jpLocked[$n])){$teacherBlockedReason='Rentang memuat JP yang sudah selesai dilaporkan. Pilih JP lain.';break;}
$teachers=kbm_pilihan_teachers($db);$state=$selected?kbm_meeting_status($selected,$now):null;
$teacherLocked=$teacherBlockedReason!==''||!empty($selected['pertemuan_id'])||!empty($selected['koreksi_id'])||!$teachers;
$success=$_SESSION['kbm_siswa_success']??'';$error=$_SESSION['kbm_siswa_error']??'';unset($_SESSION['kbm_siswa_success'],$_SESSION['kbm_siswa_error'],$_SESSION['kbm_siswa_closed']);
function kbm_p_h(mixed $s): string{return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
function kbm_p_form(string $action,int $id,string $label,string $color='primary',?int $guru=null,?int $end=null): void{
    echo '<form method="post"'.($action==='guru_hanya_tugas'?' data-confirm="Laporkan guru hanya memberikan tugas untuk seluruh rentang JP yang dipilih?"':($action==='guru_tidak_masuk'?' data-confirm="Laporkan guru ini tidak masuk untuk seluruh rentang JP yang dipilih?"':'')).'><input type="hidden" name="csrf_token" value="'.kbm_p_h($_SESSION['csrf_token']).'"><input type="hidden" name="action" value="'.$action.'"><input type="hidden" name="id" value="'.$id.'">'.($guru!==null?'<input type="hidden" name="guru_id" value="'.$guru.'">':'').($end!==null?'<input type="hidden" name="jp_selesai" value="'.$end.'">':'').'<button class="btn btn-'.$color.' fw-semibold w-100">'.$label.'</button></form>';
}
